package com.gamehub;
import com.gamehub.application.*;import com.gamehub.infrastructure.*;import org.junit.jupiter.api.Test;import java.nio.file.*;import java.time.*;import static org.junit.jupiter.api.Assertions.*;
class ReportExportRegressionTest { @Test void managerCanExportPersistedCsvAndCustomerCannot() throws Exception {Path dbPath=Files.createTempFile("report-export-", ".db"), csv=Files.createTempFile("gamehub-report-", ".csv");try(Database db=new Database(dbPath)){UserService us=new UserService(db);us.bootstrap("manager","password1");var manager=us.authenticate("manager","password1");var customer=us.registerCustomer("Report Customer","report@example.com","03001234111","password2");OperationsService o=new OperationsService(db);o.exportReportCsv(manager.id(),"Revenue",Instant.now().minusSeconds(60),Instant.now().plusSeconds(60),csv);String text=Files.readString(csv);assertTrue(text.startsWith("category,metric,value"));assertThrows(SecurityException.class,()->o.exportReportCsv(customer.id(),"Revenue",Instant.now().minusSeconds(60),Instant.now().plusSeconds(60),csv));}finally{Files.deleteIfExists(dbPath);Files.deleteIfExists(csv);}}}
